// Generated by AI
#if UNITY_EDITOR
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

/// <summary>
/// Editor tool that prepares the selected objects as absorbable waste: adds WasteItem,
/// keeps them still until absorbed, makes sure they have a collider, sets their type and
/// removes WasteItem from the group that contains them.
/// Select the individual pieces in the Hierarchy, then use Tools > S.U.C.K.-3000 > Setup Waste.
/// This file must be inside a folder named "Editor".
/// </summary>
public static class WasteSetupTool
{
    [MenuItem("Tools/S.U.C.K.-3000/Setup Waste/Plastic")]
    private static void SetupPlastic() { Setup(WasteType.Plastic); }

    [MenuItem("Tools/S.U.C.K.-3000/Setup Waste/Metal")]
    private static void SetupMetal() { Setup(WasteType.Metal); }

    [MenuItem("Tools/S.U.C.K.-3000/Setup Waste/Glass")]
    private static void SetupGlass() { Setup(WasteType.Glass); }

    [MenuItem("Tools/S.U.C.K.-3000/Setup Waste/Organic")]
    private static void SetupOrganic() { Setup(WasteType.Organic); }

    [MenuItem("Tools/S.U.C.K.-3000/Setup Waste/Electronic")]
    private static void SetupElectronic() { Setup(WasteType.Electronic); }

    private static void Setup(WasteType type)
    {
        GameObject[] selected = Selection.GetFiltered<GameObject>(
            SelectionMode.Editable | SelectionMode.ExcludePrefab);

        if (selected.Length == 0)
        {
            EditorUtility.DisplayDialog(
                "S.U.C.K.-3000",
                "Select the waste pieces in the Hierarchy first (expand the group and select its children).",
                "OK");
            return;
        }

        foreach (GameObject piece in selected)
        {
            RemoveWasteFromGroup(piece.transform.parent);
            SetupPiece(piece, type);
        }

        EditorSceneManager.MarkAllScenesDirty();
        Debug.Log(selected.Length + " object(s) set up as " + type + " waste. Save the scene with Ctrl + S.");
    }

    private static void SetupPiece(GameObject piece, WasteType type)
    {
        WasteItem item = piece.GetComponent<WasteItem>();
        if (item == null)
        {
            // WasteItem requires a Rigidbody, so Unity adds it too.
            item = Undo.AddComponent<WasteItem>(piece);
        }

        // Kinematic: the piece stays where it was placed until the vacuum takes it.
        Rigidbody body = piece.GetComponent<Rigidbody>();
        if (body != null)
        {
            Undo.RecordObject(body, "Setup waste");
            body.isKinematic = true;
        }

        EnsureCollider(piece);

        SerializedObject serialized = new SerializedObject(item);
        SerializedProperty typeProperty = serialized.FindProperty("wasteType");
        if (typeProperty != null)
        {
            typeProperty.enumValueIndex = (int)type;
        }

        serialized.ApplyModifiedProperties();
    }

    private static void EnsureCollider(GameObject piece)
    {
        if (piece.GetComponentInChildren<Collider>() != null) return;

        Renderer[] renderers = piece.GetComponentsInChildren<Renderer>();
        if (renderers.Length == 0)
        {
            Undo.AddComponent<SphereCollider>(piece);
            return;
        }

        // Box collider that fits all the meshes of the piece.
        Bounds bounds = renderers[0].bounds;
        for (int i = 1; i < renderers.Length; i++)
        {
            bounds.Encapsulate(renderers[i].bounds);
        }

        Transform pieceTransform = piece.transform;
        Vector3 scale = pieceTransform.lossyScale;

        BoxCollider box = Undo.AddComponent<BoxCollider>(piece);
        box.center = pieceTransform.InverseTransformPoint(bounds.center);
        box.size = new Vector3(
            bounds.size.x / Mathf.Max(Mathf.Abs(scale.x), 0.0001f),
            bounds.size.y / Mathf.Max(Mathf.Abs(scale.y), 0.0001f),
            bounds.size.z / Mathf.Max(Mathf.Abs(scale.z), 0.0001f));
    }

    // If a whole group was marked as waste, the group would fly as one object. Remove that.
    private static void RemoveWasteFromGroup(Transform parent)
    {
        for (Transform group = parent; group != null; group = group.parent)
        {
            WasteItem groupItem = group.GetComponent<WasteItem>();
            if (groupItem == null) continue;

            Undo.DestroyObjectImmediate(groupItem);

            Rigidbody groupBody = group.GetComponent<Rigidbody>();
            if (groupBody != null)
            {
                Undo.DestroyObjectImmediate(groupBody);
            }
        }
    }
}
#endif
